  Radio: ["Radio", "Radio"],
  ResponderActivate: ["Activate", "Methods#Activate"],
  ResponderCue: ["Cue", "Methods#Cue"],
  ResponderClearCue: ["Clear Cue", "Methods#Clear Cue"],
  ResponderEmit: ["Emit", "Methods#Emit"],
